// Ambient declarations for static asset imports. This project has no
// TypeScript installed (Vite builds via esbuild), so these self-contained
// module declarations let image imports type-check in the editor without
// depending on `vite/client` resolving.
declare module '*.png' {
  const src: string;
  export default src;
}
declare module '*.jpg' {
  const src: string;
  export default src;
}
declare module '*.jpeg' {
  const src: string;
  export default src;
}
declare module '*.gif' {
  const src: string;
  export default src;
}
declare module '*.webp' {
  const src: string;
  export default src;
}
declare module '*.svg' {
  const src: string;
  export default src;
}
